var AX_TOPO="\n<div class=\"axis-weekbar\" id=\"axisWeekBar\">\n  <button class=\"awb-brand\" id=\"awbHome\" title=\"Voltar ao AxisHub\"><span class=\"awb-mark\">\u16c9<\/span><div><b>AxisHub<\/b><span>Weekly Controller<\/span><\/div><\/button>\n  <nav class=\"awb-nav\" aria-label=\"Weekly Controller\">\n    <button data-awb-tab=\"habit\" class=\"on\">\u2713 WeekHub<\/button>\n    <button data-awb-action=\"finance\" id=\"awbFinance\">\u25c8 FinanceHub<\/button>\n    <button data-awb-tab=\"mapa\">\u25ce Mapa<\/button>\n    <button data-awb-tab=\"sono\">\u271a Sa\u00fade<\/button>\n    <button data-awb-action=\"projects\">\u25c7 Projetos<\/button>\n  <\/nav>\n  <div class=\"awb-trackers\" aria-label=\"Indicadores de hoje\">\n    <button class=\"awb-tracker expense\" id=\"awbExpense\"><span class=\"at-icon\">\u25c8<\/span><span><small>Gastos<\/small><b id=\"awbExpenseVal\">R$ 0<\/b><\/span><\/button>\n    <button class=\"awb-tracker sleep\" id=\"awbSleep\"><span class=\"at-icon\">\u263e<\/span><span><small>Sono<\/small><b id=\"awbSleepVal\">\u2014<\/b><\/span><\/button>\n    <button class=\"awb-tracker water\" id=\"awbWater\"><span class=\"at-icon\">\u25cc<\/span><span><small>\u00c1gua<\/small><b id=\"awbWaterVal\">0/8<\/b><\/span><\/button>\n    <button class=\"awb-tracker meds\" id=\"awbMeds\"><span class=\"at-icon\">\u271a<\/span><span><small>Medica\u00e7\u00e3o<\/small><b id=\"awbMedsVal\">\u2014<\/b><\/span><\/button>\n  <\/div>\n  <div class=\"awb-status\">\n    <div class=\"awb-week\"><strong id=\"awbWeekTitle\">Semana atual<\/strong><small id=\"awbWeekRange\">controle semanal<\/small><\/div>\n    <button class=\"awb-icon\" id=\"awbToday\" title=\"Ir para hoje\">\u25cf<\/button>\n  <\/div>\n<\/div>\n<div class=\"awb-dialog-backdrop\" id=\"awbWeekDialog\" aria-hidden=\"true\">\n  <section class=\"awb-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"awbWeekDialogTitle\">\n    <header class=\"awb-dialog-head\"><div><small>WEEKHUB \u00b7 CONTROLE INTEGRADO<\/small><h2 id=\"awbWeekDialogTitle\">Painel semanal<\/h2><\/div><button id=\"awbWeekClose\" aria-label=\"Fechar\">\u00d7<\/button><\/header>\n    <div class=\"awb-dialog-body\" id=\"awbWeekDialogBody\"><\/div>\n  <\/section>\n<\/div>\n\n\n\n<div id=\"toolDock\">\n  <div class=\"td-panel\">\n    <header class=\"td-phd\"><div><div class=\"td-peb\" id=\"dockEb\">torre de controle<\/div><h2 id=\"dockTitle\">Centro de Comando<\/h2><\/div><button class=\"td-px\" id=\"dockClose\" aria-label=\"Fechar\">\u00d7<\/button><\/header>\n    <div class=\"td-pbody\" id=\"dockBody\" style=\"position:relative\"><\/div>\n    <button class=\"projfab\" id=\"projFab\" title=\"Projetos & Retomadas\" style=\"position:absolute;left:-99px;top:33px\">\ud83d\uddc2 <span>Projetos<\/span><\/button>\n  <\/div>\n<\/div>\n\n\n\n<!-- Yggdrasil \u2014 overlay de navega\u00e7\u00e3o entre mundos -->\n\n<div id=\"yggRail\" style=\"position:absolute;left:-9px;top:-11px\"><\/div>\n<div id=\"mgDock\">\n  <button class=\"mg-handle\" id=\"mgHandle\" aria-label=\"Painel de planners\">\u27e9<\/button>\n  <div class=\"mg-inner\">\n    <div class=\"mg-eb\">Painel gerencial<\/div>\n    <div class=\"mg-cards\" id=\"mgBody\"><\/div>\n    <div class=\"mg-foot\" id=\"mgFoot\"><\/div>\n  <\/div>\n<\/div>\n<div id=\"yggTree\">\n  <div class=\"yscrim\"><\/div>\n  <div class=\"ysheet\">\n    <div class=\"ycard\">\n      <button id=\"yggClose\" aria-label=\"Fechar\">\u00d7<\/button>\n      <div class=\"yhead\">\n        <div class=\"yeb\">yggdrasil \u00b7 axis mundi<\/div>\n        <div class=\"yt\">A \u00e1rvore dos seus mundos<\/div>\n        <div class=\"ysub\">Um eixo, muitos mundos. Escolha um galho.<\/div>\n      <\/div>\n      <div id=\"yggNodes\"><\/div>\n      <div class=\"yfoot\">um eixo \u00b7 seis mundos<\/div>\n    <\/div>\n  <\/div>\n<\/div>\n\n<!-- ===== Reposit\u00f3rio / Biblioteca de mundos ===== -->\n\n\n<div id=\"gtOverlay\">\n  <div class=\"gt-scrim\" data-gt-close=\"\"><\/div>\n  <div class=\"gt-shell\">\n    <header class=\"gt-top\">\n      <div><div class=\"gt-eb\" id=\"gtEb\">torre de controle<\/div><h2 id=\"gtTitle\">Centro de Comando<\/h2><\/div>\n      <button class=\"rp-x\" data-gt-close=\"\" aria-label=\"Fechar\">\u00d7<\/button>\n    <\/header>\n    <div class=\"gt-body\" id=\"gtBody\"><\/div>\n  <\/div>\n<\/div>\n<div id=\"repoOverlay\">\n  <div class=\"rp-scrim\" data-repo-close=\"\"><\/div>\n  <div class=\"rp-shell\">\n    <header class=\"rp-top\">\n      <div>\n        <div class=\"rp-eb\">reposit\u00f3rio \u00b7 axis mundi<\/div>\n        <h2>Biblioteca de mundos<\/h2>\n      <\/div>\n      <div class=\"rp-actions\">\n        <div class=\"rp-meter\" id=\"rpMeter\"><\/div>\n        <button class=\"rp-import\" id=\"rpImport\"><span>\uff0b<\/span> Importar<\/button>\n        <button class=\"rp-x\" data-repo-close=\"\" aria-label=\"Fechar\">\u00d7<\/button>\n      <\/div>\n    <\/header>\n    <div class=\"rp-body\">\n      <nav class=\"rp-rail\" id=\"rpRail\"><\/nav>\n      <section class=\"rp-main\">\n        <div class=\"rp-search\">\n          <input id=\"rpSearch\" placeholder=\"Buscar arquivo\u2026\" autocomplete=\"off\">\n          <div class=\"rp-drop\" id=\"rpDrop\">Arraste planners aqui ou toque em Importar<\/div>\n        <\/div>\n        <div class=\"rp-grid\" id=\"rpGrid\"><\/div>\n      <\/section>\n    <\/div>\n  <\/div>\n  <input type=\"file\" id=\"rpFile\" multiple accept=\"image/*,application/pdf,.pdf\" style=\"display:none\">\n<\/div>\n<div id=\"rpViewer\">\n  <div class=\"rv-scrim\" data-rv-close=\"\"><\/div>\n  <div class=\"rv-shell\">\n    <header class=\"rv-top\">\n      <div class=\"rv-meta\" id=\"rvMeta\"><\/div>\n      <div class=\"rv-tools\" id=\"rvTools\"><\/div>\n      <button class=\"rv-x\" data-rv-close=\"\" aria-label=\"Fechar\">\u00d7<\/button>\n    <\/header>\n    <div class=\"rv-stage\" id=\"rvStage\"><\/div>\n  <\/div>\n<\/div>\n\n<!-- Modais -->\n<div class=\"modal\" id=\"entryModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Novo lan\u00e7amento<\/h3>\n    <div class=\"fr\"><label>Natureza<\/label>\n      <div class=\"seg\" id=\"entrySeg\">\n        <button data-tipo=\"entrada\" class=\"on\">Receita<\/button>\n        <button data-tipo=\"investimento\">Investim.<\/button>\n        <button data-tipo=\"fixo\">Desp. fixa<\/button>\n        <button data-tipo=\"variavel\">Desp. vari\u00e1vel<\/button>\n        <button data-tipo=\"anual\">Anual/event.<\/button>\n      <\/div><\/div>\n    <div class=\"fr\" id=\"catWrap\"><label>Categoria (grupo \u203a subcategoria)<\/label><select id=\"enSub\"><\/select><\/div>\n    <div class=\"fr\"><label>Descri\u00e7\u00e3o<\/label><input id=\"enDesc\" placeholder=\"Detalhe livre, ex.: Mercado da semana\"><\/div>\n    <div class=\"fr\" id=\"meioWrap\"><label>Meio de pagamento<\/label><input id=\"enMeio\" placeholder=\"Ex.: D\u00e9bito autom\u00e1tico, PIX, corretora\"><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label id=\"lblDPrev\">Data prevista<\/label><input id=\"enDPrev\" type=\"date\"><\/div>\n      <div class=\"fr\" id=\"dRealWrap\"><label id=\"lblDReal\">Data de recebimento<\/label><input id=\"enDReal\" type=\"date\"><\/div>\n      <div class=\"fr\" id=\"statusWrap\" style=\"display:none\"><label>Status<\/label><select id=\"enStatus\"><option value=\"Previsto\">Previsto<\/option><option value=\"Aportado\">Aportado<\/option><option value=\"Atrasado\">Atrasado<\/option><\/select><\/div><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label id=\"lblPrev\">Valor previsto (R$)<\/label><input id=\"enVal\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div>\n      <div class=\"fr\"><label id=\"lblEfet\">Valor efetivo (R$)<\/label><input id=\"enEfet\" inputmode=\"decimal\" placeholder=\"opcional\"><\/div><\/div>\n    <div class=\"fr\"><label><input type=\"checkbox\" id=\"enRec\" style=\"width:auto;margin-right:8px;vertical-align:-2px\">Repete todo m\u00eas (recorrente)<\/label><\/div>\n    <button class=\"btn\" id=\"enSave\">Salvar lan\u00e7amento<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n<div class=\"modal\" id=\"cardModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Nova compra parcelada<\/h3>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Bandeira / cart\u00e3o<\/label><input id=\"cdBand\" placeholder=\"Ex.: BB F\u00e1cil\"><\/div>\n      <div class=\"fr\"><label>Descri\u00e7\u00e3o<\/label><input id=\"cdDesc\" placeholder=\"Ex.: Notebook\"><\/div><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Valor da parcela (R$)<\/label><input id=\"cdVal\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div>\n      <div class=\"fr\"><label>N\u00ba de parcelas<\/label><input id=\"cdParc\" type=\"number\" inputmode=\"numeric\" min=\"1\" value=\"1\"><\/div><\/div>\n    <div class=\"fr\"><label>Primeira parcela em<\/label><input id=\"cdIni\" type=\"month\"><\/div>\n    <button class=\"btn\" id=\"cdSave\">Salvar compra<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n<div class=\"modal\" id=\"planModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Novo plano<\/h3>\n    <div class=\"fr\"><label>O que \u00e9<\/label><input id=\"plTitulo\" placeholder=\"Ex.: Viagem para Nova York\"><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Tipo<\/label><select id=\"plTipo\"><option value=\"viagem\">Viagem \u2708\ufe0f<\/option><option value=\"compra\">Compra \ud83d\udecd\ufe0f<\/option><option value=\"outro\">Outro \u25c7<\/option><\/select><\/div>\n      <div class=\"fr\"><label>Valor total (R$)<\/label><input id=\"plValor\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Parcelas<\/label><input id=\"plParc\" type=\"number\" inputmode=\"numeric\" min=\"1\" value=\"1\"><\/div>\n      <div class=\"fr\"><label>Come\u00e7a em<\/label><input id=\"plInicio\" type=\"month\"><\/div><\/div>\n    <div class=\"fr\"><label>Categoria do lan\u00e7amento (grupo \u203a subcategoria)<\/label><select id=\"plSub\"><\/select><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Data prevista<\/label><input id=\"plDPrev\" type=\"date\"><\/div>\n      <div class=\"fr\"><label>Meio de pagamento<\/label><input id=\"plMeio\" placeholder=\"Ex.: Cart\u00e3o, PIX\"><\/div><\/div>\n    <button class=\"btn\" id=\"plSave\">Salvar plano<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"verModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Nova vers\u00e3o da viagem<\/h3>\n    <div class=\"fr\"><label>Nome da vers\u00e3o<\/label><input id=\"vrNome\" placeholder=\"Ex.: Setembro econ\u00f4mico\"><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Parcelas<\/label><input id=\"vrParc\" type=\"number\" inputmode=\"numeric\" min=\"1\" value=\"6\"><\/div>\n      <div class=\"fr\"><label>Come\u00e7a em<\/label><input id=\"vrIni\" type=\"month\"><\/div><\/div>\n    <div class=\"fr\"><label><input type=\"checkbox\" id=\"vrCopy\" style=\"width:auto;margin-right:8px;vertical-align:-2px\" checked=\"\">Copiar roteiro e caixa da vers\u00e3o atual<\/label><\/div>\n    <button class=\"btn\" id=\"vrSave\">Criar vers\u00e3o<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"stepModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Etapa do roteiro<\/h3>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Dia<\/label><input id=\"stDia\" type=\"number\" inputmode=\"numeric\" min=\"1\" value=\"1\"><\/div>\n      <div class=\"fr\"><label>Custo (R$)<\/label><input id=\"stCusto\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div><\/div>\n    <div class=\"fr\"><label>Atividade<\/label><input id=\"stAtiv\" placeholder=\"Ex.: Empire State + compras\"><\/div>\n    <button class=\"btn\" id=\"stSave\">Adicionar etapa<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"caixaModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Item do livro-caixa<\/h3>\n    <div class=\"fr\"><label>Item<\/label><input id=\"cxItem\" placeholder=\"Ex.: Voo / Hospedagem / Seguro\"><\/div>\n    <div class=\"fr\"><label>Valor (R$)<\/label><input id=\"cxValor\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div>\n    <button class=\"btn\" id=\"cxSave\">Adicionar ao caixa<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"consModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Consignado<\/h3>\n    <div class=\"fr\"><label>Nome<\/label><input id=\"coNome\" placeholder=\"Ex.: Consignado BB 1\"><\/div>\n    <div class=\"two\">\n      <div class=\"fr\"><label>Parcela (R$)<\/label><input id=\"coVal\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div>\n      <div class=\"fr\"><label>Termina em<\/label><input id=\"coFim\" type=\"month\"><\/div><\/div>\n    <button class=\"btn\" id=\"coSave\">Salvar<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n\n\n<div class=\"modal\" id=\"blockModal\">\n  <div class=\"scrim\" id=\"bmScrim\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Bloco da semana<\/h3>\n    <div class=\"fr\"><label>T\u00edtulo<\/label><input id=\"bmTitle\" placeholder=\"Nome do bloco\"><\/div>\n    <div class=\"fr\" style=\"display:flex;gap:8px\">\n      <label style=\"flex:1\"><span style=\"display:block;margin-bottom:4px\">In\u00edcio<\/span><input id=\"bmStart\" type=\"time\" step=\"900\" style=\"width:100%\"><\/label>\n      <label style=\"flex:1\"><span style=\"display:block;margin-bottom:4px\">Fim<\/span><input id=\"bmEnd\" type=\"time\" step=\"900\" style=\"width:100%\"><\/label>\n    <\/div>\n    <div class=\"fr\"><label>Categoria<\/label><select id=\"bmArea\" style=\"width:100%\"><\/select><\/div>\n    <div class=\"fr\"><label>Fun\u00e7\u00e3o<\/label><textarea id=\"bmDesc\" rows=\"2\" placeholder=\"O que este bloco cumpre\u2026\"><\/textarea><\/div>\n    <div class=\"fr\"><label>Nota<\/label><textarea id=\"bmNota\" rows=\"2\" placeholder=\"Anota\u00e7\u00e3o livre\u2026\"><\/textarea><\/div>\n    <div class=\"fr\"><label class=\"bmindisplabel\"><input type=\"checkbox\" id=\"bmIndisp\" style=\"width:auto;margin-right:8px;vertical-align:-2px\">Marcar como indispens\u00e1vel (aparece na barra principal)<\/label><\/div>\n    <button class=\"btn\" id=\"bmDone\">Conclu\u00eddo<\/button>\n    <button class=\"btn ghost\" id=\"bmDelete\">Excluir bloco<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"wtSchedModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Atribuir dia e hor\u00e1rio<\/h3>\n    <div class=\"fr\"><label>Dia da semana<\/label><select id=\"wtSchedDay\"><option value=\"0\">Segunda<\/option><option value=\"1\">Ter\u00e7a<\/option><option value=\"2\">Quarta<\/option><option value=\"3\">Quinta<\/option><option value=\"4\">Sexta<\/option><option value=\"5\">S\u00e1bado<\/option><option value=\"6\">Domingo<\/option><\/select><\/div>\n    <div class=\"fr\"><label>Hor\u00e1rio<\/label><input id=\"wtSchedTime\" type=\"time\" value=\"09:00\"><\/div>\n    <button class=\"btn\" id=\"wtSchedSet\">Atribuir<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"gastoModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Registrar gasto<\/h3>\n    <div class=\"fr\"><label>Nome do gasto<\/label><input id=\"gastoNome\" placeholder=\"Ex.: Almo\u00e7o, Uber, Farm\u00e1cia\u2026\"><\/div>\n    <div class=\"fr\"><label>Valor (R$)<\/label><input id=\"gastoValor\" inputmode=\"decimal\" placeholder=\"0,00\"><\/div>\n    <div class=\"fr\"><label>Data<\/label><input id=\"gastoData\" type=\"date\"><\/div>\n    <button class=\"btn\" id=\"gastoSave\">Registrar gasto<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"mealModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Registrar refei\u00e7\u00e3o<\/h3>\n    <div class=\"fr\"><label>Refei\u00e7\u00f5es padr\u00e3o<\/label><div class=\"mealpresets\" id=\"mealPresets\"><\/div><\/div>\n    <div class=\"fr\"><label>Nova refei\u00e7\u00e3o padr\u00e3o<\/label><div style=\"display:flex;gap:8px\"><input id=\"mealPresetNew\" placeholder=\"Ex.: Pr\u00e9-treino\" style=\"flex:1\"><button class=\"btn\" id=\"mealPresetAdd\" style=\"width:auto;padding:10px 16px;margin-top:0\">+ salvar<\/button><\/div><\/div>\n    <div class=\"fr\"><label>Refei\u00e7\u00e3o<\/label><input id=\"mealName\" placeholder=\"Nome da refei\u00e7\u00e3o\"><\/div>\n    <div class=\"fr\"><label>Hor\u00e1rio<\/label><input id=\"mealTime\" type=\"time\"><\/div>\n    <button class=\"btn\" id=\"mealSave\">Registrar refei\u00e7\u00e3o<\/button>\n    <div class=\"fr\"><label>Hoje<\/label><div class=\"meallogedit\" id=\"mealLogEdit\"><\/div><\/div>\n    <button class=\"btn ghost\" data-close=\"\">Fechar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"saudeModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3 id=\"saudeTitle\">Registro<\/h3>\n    <div id=\"saudeBody\"><\/div>\n    <button class=\"btn\" id=\"saudeSave\">Salvar<\/button>\n    <button class=\"btn ghost\" id=\"saudeDel\">Excluir<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"goalModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Meta de vida<\/h3>\n    <div class=\"fr\"><label>T\u00edtulo<\/label><input id=\"goalTitle\" placeholder=\"Ex.: Recuperar a melhor forma f\u00edsica\"><\/div>\n    <div class=\"fr\"><label>\u00c1rea da vida<\/label><select id=\"goalArea\"><\/select><\/div>\n    <div class=\"fr\"><label>Por qu\u00ea (motiva\u00e7\u00e3o)<\/label><textarea id=\"goalWhy\" rows=\"2\" placeholder=\"O que essa meta destrava na sua vida\"><\/textarea><\/div>\n    <div class=\"fr\"><label>Alvo concreto<\/label><input id=\"goalTarget\" placeholder=\"Ex.: Treino 4x/semana + 12% BF\"><\/div>\n    <div class=\"fr\"><label>Horizonte<\/label><input id=\"goalHorizon\" placeholder=\"Ex.: 2026\"><\/div>\n    <div class=\"fr\"><label>Progresso: <b id=\"goalProgV\">0%<\/b><\/label><input id=\"goalProg\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" style=\"width:100%\"><\/div>\n    <button class=\"btn\" id=\"goalSave\">Salvar meta<\/button>\n    <button class=\"btn ghost\" id=\"goalDel\">Excluir<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"capEditModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Editar registro<\/h3>\n    <p class=\"wknhint\" id=\"capEditTxt\"><\/p>\n    <div style=\"display:flex;gap:8px;margin-bottom:8px\">\n      <label class=\"qnalw\" style=\"flex:1\"><span class=\"qnalk\">\ud83d\udcc5<\/span><input id=\"capEditDate\" type=\"date\" class=\"qnsel qnalarm\" style=\"flex:1\"><\/label>\n      <label class=\"qnalw\" style=\"flex:1\"><span class=\"qnalk\">\u23f0<\/span><input id=\"capEditTime\" type=\"time\" class=\"qnsel qnalarm\" style=\"flex:1\"><\/label>\n    <\/div>\n    <div style=\"display:flex;gap:8px;margin-bottom:10px\">\n      <select id=\"capEditArea\" class=\"qnsel\" style=\"flex:1\"><\/select>\n      <select id=\"capEditGoal\" class=\"qnsel\" style=\"flex:1\"><\/select>\n    <\/div>\n    <button class=\"btn\" id=\"capEditSave\">Salvar<\/button>\n    <button class=\"btn ghost\" id=\"capEditClear\">Limpar data<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"rtSchedModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Agendar no dia<\/h3>\n    <p class=\"wknhint\" id=\"rtSchedTxt\"><\/p>\n    <div style=\"display:flex;gap:8px;margin-bottom:4px\">\n      <select id=\"rtSchedDay\" class=\"qnsel\" style=\"flex:1\"><\/select>\n      <select id=\"rtSchedHour\" class=\"qnsel\" style=\"flex:1\"><\/select>\n    <\/div>\n    <button class=\"btn\" id=\"rtSchedSet\">Lan\u00e7ar no hor\u00e1rio da Semana<\/button>\n    <button class=\"btn ghost\" data-close=\"\">Cancelar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"qnAlarmModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Alarme da nota<\/h3>\n    <p class=\"wknhint\" id=\"qnAlarmTxt\"><\/p>\n    <input type=\"datetime-local\" id=\"qnAlarmInput\" class=\"qnsel\" style=\"width:100%;box-sizing:border-box\">\n    <div style=\"display:flex;gap:8px;margin-top:14px\">\n      <button class=\"btn\" id=\"qnAlarmSet\">Definir alarme<\/button>\n      <button class=\"btn ghost\" id=\"qnAlarmClear\">Remover alarme<\/button>\n    <\/div>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"wkNoteModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3 id=\"wkNoteTitle\">Inegoci\u00e1veis di\u00e1rios<\/h3>\n    <p class=\"wknhint\" id=\"wkNoteHint\"><\/p>\n    <textarea id=\"wkNoteBox\" class=\"wknarea\" data-wp=\"inegociaveis\"><\/textarea>\n    <button class=\"btn\" id=\"wkNoteDone\">Pronto<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"desafioModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Adicionar desafio<\/h3>\n    <div id=\"desafioPicker\"><\/div>\n    <button class=\"btn ghost\" data-close=\"\">Fechar<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"modal\" id=\"syncModal\">\n  <div class=\"scrim\" data-close=\"\"><\/div>\n  <div class=\"sheet\"><div class=\"grip\"><\/div>\n    <h3>Sincronizar com o Drive<\/h3>\n    <p class=\"intro\" style=\"margin:0 0 12px\">Cole aqui o endere\u00e7o do seu app da web do Google Apps Script. A partir da\u00ed, cada lan\u00e7amento \u00e9 enviado para a planilha no seu Drive. (Passo a passo no README do projeto.)<\/p>\n    <div class=\"fr\"><label>URL do app da web (termina em /exec)<\/label><input id=\"syncInput\" placeholder=\"https://script.google.com/macros/s/.../exec\"><\/div>\n    <button class=\"btn\" id=\"syncSave\">Salvar e ativar<\/button>\n    <button class=\"btn ghost\" id=\"syncTest\">Enviar agora (testar)<\/button>\n    <button class=\"btn ghost\" id=\"syncClear\">Desativar sincroniza\u00e7\u00e3o<\/button>\n  <\/div>\n<\/div>\n\n\n\n\n\n\n\n\n\n<div class=\"awb-quick-pop\" id=\"awbQuickPop\"><\/div>\n\n\n\n<div class=\"health-med-dialog\" id=\"healthMedDialog\"><div class=\"health-med-box\"><header><h3 id=\"healthMedTitle\">Nova medica\u00e7\u00e3o<\/h3><button data-health-med-close>\u00d7<\/button><\/header><div class=\"health-med-form\"><label class=\"wide\">Nome<input id=\"healthMedName\" placeholder=\"Ex.: Venvanse\"><\/label><label>Dose / apresenta\u00e7\u00e3o<input id=\"healthMedDose\" placeholder=\"Ex.: 30 mg\"><\/label><label>Quantidade por hor\u00e1rio<input id=\"healthMedQty\" type=\"number\" min=\"1\" step=\"1\" value=\"1\"><\/label><label class=\"wide\">Hor\u00e1rios separados por v\u00edrgula<input id=\"healthMedTimes\" placeholder=\"08:00, 14:00, 22:00\"><\/label><footer><button data-health-med-close>Cancelar<\/button><button class=\"health-med-save\" data-health-med-save>Salvar medica\u00e7\u00e3o<\/button><\/footer><\/div><\/div><\/div>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n";
var AX_HUB="<div class=\"wrap\">\n  <header style=\"width:316px;height:894px\">\n    <div class=\"brandline\">\n      <span class=\"eyebrow\" id=\"eyebrow\">meu habit tracker \u00b7 bruno dutra<\/span>\n      <button class=\"modebtn\" id=\"modeBtnTop\" aria-label=\"Abrir a \u00e1rvore Yggdrasil \u2014 trocar de mundo\" title=\"Abrir a \u00e1rvore \u2014 trocar de mundo\" style=\"font-size:14px\">\u16c9<\/button>\n    <\/div>\n    <div class=\"monthnav\">\n      <div class=\"navrow\">\n        <button class=\"navbtn\" id=\"prevM\" aria-label=\"Anterior\">\u2039<\/button>\n        <h1 id=\"monthLabel\">\u2014<\/h1>\n        <button class=\"navbtn\" id=\"nextM\" aria-label=\"Pr\u00f3ximo\">\u203a<\/button>\n      <\/div>\n      <button class=\"viewtog\" id=\"viewTog\">Ano<\/button>\n      <div class=\"mg-cal-inline\" id=\"mgCalInline\"><\/div>\n    <\/div>\n    <div class=\"mg-quicktrk\" id=\"mgQuickTrk\"><\/div>\n    <div class=\"tabswrap\">\n      <div class=\"logoaneox tabslogo\"><img src=\"data:image/png;base64,\" alt=\"aneox\"><\/div>\n      <div class=\"tabs\" id=\"mainTabs\" role=\"tablist\">\n      <button class=\"tab\" role=\"tab\" data-tab=\"mes\" aria-selected=\"true\">M\u00eas<\/button>\n      <button class=\"tab\" role=\"tab\" data-tab=\"previsao\" aria-selected=\"false\">Previs\u00e3o<\/button>\n      <button class=\"tab\" role=\"tab\" data-tab=\"planejar\" aria-selected=\"false\">Planejar<\/button>\n      <button class=\"tab\" role=\"tab\" data-tab=\"desafios\" aria-selected=\"false\">Metas<\/button>\n    <\/div>\n    <\/div>\n  <\/header>\n\n  <div id=\"flipzone\">\n  <main>\n    <!-- M\u00caS / ANUAL -->\n    <section class=\"panel on\" id=\"p-mes\">\n      <div id=\"mesNormal\">\n        <div class=\"balance\">\n          <div class=\"lbl\">Balan\u00e7o do m\u00eas<\/div>\n          <div class=\"big\" id=\"balBig\">R$ 0<\/div>\n          <div class=\"brk\">\n            <span>Entradas previstas \u00b7 bruto<b id=\"balInPrev\">R$ 0<\/b><\/span>\n            <span>Entradas efetivas \u00b7 l\u00edquido<b id=\"balInEfet\">R$ 0<\/b><\/span>\n            <span>Gastos previstos \u00b7 c/ cart\u00f5es<b id=\"balOutPrev\">R$ 0<\/b><\/span>\n            <span>Gastos efetivos<b id=\"balOutEfet\">R$ 0<\/b><\/span>\n          <\/div>\n        <\/div>\n        <div class=\"sec\" id=\"secCategorias\"><\/div>\n        <div class=\"sec\" id=\"secEntradas\"><\/div>\n      <\/div>\n      <div id=\"anualView\" style=\"display:none\"><\/div>\n    <\/section>\n\n    <!-- PREVIS\u00c3O + COMPROMISSOS -->\n    <section class=\"panel\" id=\"p-previsao\">\n      <div class=\"vsection\">\ud83d\udcc8 Proje\u00e7\u00e3o m\u00eas a m\u00eas \u2014 compromissos e saldo livre<\/div>\n      <div id=\"secTimeline\"><\/div>\n      <div id=\"projEditor\" style=\"display:block\">\n        <div class=\"vsection\" style=\"opacity: 0\">\ud83d\udd13 Compromissos e consignados<\/div>\n        <div class=\"sec\" id=\"secConsignados\"><\/div>\n        <div class=\"vsection\" style=\"opacity: 0\">\ud83d\udcb3 Cart\u00f5es e parcelas futuras<\/div>\n        <div class=\"sec\" id=\"secParcelamentos\"><\/div>\n        <button class=\"addbtn\" id=\"cardNew\">+ Novo parcelamento<\/button>\n        <div class=\"sec\" id=\"secFaturas\"><\/div>\n      <\/div>\n      <div class=\"tip tipcard\">\n        <div class=\"tt\">\u23f3 Juros compostos: seu maior aliado<\/div>\n        <div class=\"tb\">O dinheiro que sobra pode render dinheiro. <b>R$ 200/m\u00eas a 10% ao ano<\/b> viram cerca de <b>R$ 38 mil em 10 anos<\/b> e <b>R$ 452 mil em 30<\/b>. Quanto mais cedo come\u00e7a, mais o tempo trabalha por voc\u00ea. Comece pequeno, seja constante.<\/div>\n      <\/div>\n      <div class=\"tip gold tipcard\">\n        <div class=\"tt\">\ud83d\udcb3 Distribua suas despesas no cart\u00e3o<\/div>\n        <div class=\"tb\">Uma forma de organizar: <b>Cart\u00e3o 1<\/b> para essenciais (alimenta\u00e7\u00e3o, sa\u00fade, transporte, internet), <b>Cart\u00e3o 2<\/b> para parceladas essenciais (reformas, viagens, itens de trabalho) e <b>Cart\u00e3o 3<\/b> para o que n\u00e3o \u00e9 essencial. Mire <b>50%<\/b> essenciais \u00b7 <b>30%<\/b> parceladas \u00b7 <b>20%<\/b> n\u00e3o-essencial.<\/div>\n      <\/div>\n      <div class=\"tip tipcard\">\n        <div class=\"tt\">\ud83d\udcc5 Fatura, fechamento e vencimento<\/div>\n        <div class=\"tb\"><b>Fechamento<\/b> \u00e9 o dia em que a fatura \"fecha\"; <b>vencimento<\/b> \u00e9 o prazo final sem juros. Comprar logo ap\u00f3s o fechamento d\u00e1 quase 40 dias at\u00e9 pagar. Atraso vira d\u00edvida de juros altos \u2014 a que mais corr\u00f3i o or\u00e7amento.<\/div>\n      <\/div>\n    <\/section>\n\n    <!-- PLANEJAR -->\n    <section class=\"panel\" id=\"p-planejar\">\n      <p class=\"intro\">Lance uma viagem ou compra grande e veja, na Previs\u00e3o, como ela pesa nos meses \u00e0 frente \u2014 para decidir antes de comprar.<\/p>\n      <div id=\"planList\"><\/div>\n      <button class=\"addbtn\" id=\"planNew\">+ Novo plano de compra ou viagem<\/button>\n    <\/section>\n\n    <!-- METAS -->\n    <section class=\"panel\" id=\"p-desafios\">\n      <p class=\"intro\">Onde tudo aponta para frente: a evolu\u00e7\u00e3o financeira no topo, suas metas de curto e longo prazo com m\u00e9todo logo abaixo, a board de desafios que voc\u00ea monta, e a linha do tempo financeira ao final.<\/p>\n      <div id=\"evolucao\"><\/div>\n      <div id=\"metasPainel\"><\/div>\n      <button class=\"addbtn\" id=\"addDesafio\">+ Adicionar desafio \u00e0 board<\/button>\n      <div id=\"board\"><\/div>\n      <div id=\"linhaTempo\"><\/div>\n    <\/section>\n\n    <!-- HABIT TRACKER \u2014 usa o mesmo palco das abas -->\n    <section class=\"panel\" id=\"p-habit\">\n      <div id=\"habitApp\"><\/div>\n    <\/section>\n\n    <!-- GALHO A BROTAR (mundos futuros) -->\n    <section class=\"panel\" id=\"p-seed\">\n      <div id=\"seedApp\"><\/div>\n    <\/section>\n  <\/main>\n  <\/div>\n<\/div>";
